import{_ as a,o as t,c as i,ag as o}from"./chunks/framework.CPvOxTBX.js";const p=JSON.parse('{"title":"FAQ","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md","lastUpdated":1793283000000}'),s={name:"guide/faq.md"};function r(n,e,d,h,l,c){return t(),i("div",null,e[0]||(e[0]=[o(`<h1 id="faq" tabindex="-1">FAQ <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;FAQ&quot;">​</a></h1><h2 id="where-do-i-get-dictionaries" tabindex="-1">Where do I get dictionaries? <a class="header-anchor" href="#where-do-i-get-dictionaries" aria-label="Permalink to &quot;Where do I get dictionaries?&quot;">​</a></h2><p>Ciyue does not ship with dictionaries. Download <code>.mdx</code> / <code>.mdd</code> files, or StarDict dictionaries (<code>.ifo</code> / <code>.idx</code> / <code>.dict</code>), from the <a href="https://github.com/mumu-lhl/Ciyue/wiki#recommended-dictionaries" target="_blank" rel="noreferrer">recommended dictionaries</a> list on the Wiki, then add them in <strong>Settings → Manage dictionaries</strong>.</p><h2 id="why-does-ciyue-need-the-internet-permission" tabindex="-1">Why does Ciyue need the INTERNET permission? <a class="header-anchor" href="#why-does-ciyue-need-the-internet-permission" aria-label="Permalink to &quot;Why does Ciyue need the INTERNET permission?&quot;">​</a></h2><p>Ciyue uses WebView to render dictionary entries, and WebView requires the INTERNET permission to work — even when displaying local data. The permission is also used for update checks and third-party services you configure (such as an AI provider). Ciyue never initiates network requests on its own.</p><h2 id="the-f-droid-version-is-older-than-the-github-release-why" tabindex="-1">The F-Droid version is older than the GitHub release. Why? <a class="header-anchor" href="#the-f-droid-version-is-older-than-the-github-release-why" aria-label="Permalink to &quot;The F-Droid version is older than the GitHub release. Why?&quot;">​</a></h2><p>F-Droid builds and publishes apps on its own schedule, so its releases can lag behind GitHub by days or weeks. If you want updates as soon as they are published, install via <a href="https://obtainium.imranr.dev/" target="_blank" rel="noreferrer">Obtainium</a>, which tracks GitHub releases directly — tap the Obtainium badge on the <a href="./getting-started.html">Getting Started</a> page.</p><h2 id="how-do-app-updates-work-what-are-the-update-channels" tabindex="-1">How do app updates work? What are the update channels? <a class="header-anchor" href="#how-do-app-updates-work-what-are-the-update-channels" aria-label="Permalink to &quot;How do app updates work? What are the update channels?&quot;">​</a></h2><p>On <strong>Settings → Check for updates</strong> you can choose an update channel:</p><ul><li><strong>Stable</strong> — official releases only (recommended for most users).</li><li><strong>Beta / Alpha</strong> — prereleases with new features that are still being tested.</li><li><strong>Nightly</strong> — automatic daily builds with the latest changes; may be unstable.</li></ul><p>Desktop apps use the same three channels through the built-in updater.</p><h2 id="how-do-i-back-up-my-wordbook-and-settings" tabindex="-1">How do I back up my wordbook and settings? <a class="header-anchor" href="#how-do-i-back-up-my-wordbook-and-settings" aria-label="Permalink to &quot;How do I back up my wordbook and settings?&quot;">​</a></h2><p>Go to <strong>Settings → Backup</strong> to export your data (wordbook, history, tags, flashcards, settings) to a file. Keep that file somewhere safe; you can import it later on the same screen. For continuous multi-device sync, see <a href="./cloud-sync.html">Cloud Sync</a>.</p><h2 id="a-dictionary-shows-garbled-or-missing-content-what-can-i-do" tabindex="-1">A dictionary shows garbled or missing content. What can I do? <a class="header-anchor" href="#a-dictionary-shows-garbled-or-missing-content-what-can-i-do" aria-label="Permalink to &quot;A dictionary shows garbled or missing content. What can I do?&quot;">​</a></h2><ul><li>Make sure the matching <code>.mdd</code> resource file (if the dictionary has one) is placed next to the <code>.mdx</code> file with the same base name.</li><li>For a StarDict dictionary, keep its <code>.ifo</code>, <code>.idx</code>, and <code>.dict</code> files together under the same base name.</li><li>Some dictionaries need a custom CSS tweak: <strong>Manage dictionaries → dictionary → Custom CSS</strong>.</li><li>If a dictionary crashes the lookup, please <a href="https://github.com/mumu-lhl/Ciyue/issues" target="_blank" rel="noreferrer">open an issue</a> with the dictionary name.</li></ul><h2 id="how-do-i-use-ciyue-with-koreader-on-android" tabindex="-1">How do I use Ciyue with KOReader on Android? <a class="header-anchor" href="#how-do-i-use-ciyue-with-koreader-on-android" aria-label="Permalink to &quot;How do I use Ciyue with KOReader on Android?&quot;">​</a></h2><p>Create a file named <code>dictionaries.lua</code> inside the <code>koreader</code> directory with:</p><div class="language-lua vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">lua</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    { </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ciyue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;Ciyue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;org.eu.mumulhl.ciyue&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;send&quot; </span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Then look up words from KOReader via the dictionary action.</p><h2 id="where-is-my-data-stored" tabindex="-1">Where is my data stored? <a class="header-anchor" href="#where-is-my-data-stored" aria-label="Permalink to &quot;Where is my data stored?&quot;">​</a></h2><ul><li><strong>Android</strong>: the app&#39;s private storage (<code>/data/data/org.eu.mumulhl.ciyue/</code>); dictionaries default to the app&#39;s documents directory, configurable in settings.</li><li><strong>Windows</strong>: <code>%APPDATA%\\ciyue\\</code>.</li><li><strong>Linux</strong>: <code>~/.local/share/ciyue/</code> (or <code>~/.var/app/...</code> for Flatpak).</li><li><strong>macOS</strong>: <code>~/Library/Application Support/ciyue/</code>.</li></ul><h2 id="how-can-i-contribute-translations" tabindex="-1">How can I contribute translations? <a class="header-anchor" href="#how-can-i-contribute-translations" aria-label="Permalink to &quot;How can I contribute translations?&quot;">​</a></h2><p>Translations are managed on <a href="https://hosted.weblate.org/engage/ciyue/" target="_blank" rel="noreferrer">Weblate</a>. You can add a new language or improve existing translations there — no coding needed.</p><h2 id="i-found-a-bug-have-a-feature-request-where-do-i-report-it" tabindex="-1">I found a bug / have a feature request. Where do I report it? <a class="header-anchor" href="#i-found-a-bug-have-a-feature-request-where-do-i-report-it" aria-label="Permalink to &quot;I found a bug / have a feature request. Where do I report it?&quot;">​</a></h2><p>Open an issue on <a href="https://github.com/mumu-lhl/Ciyue/issues" target="_blank" rel="noreferrer">GitHub</a>. Please include your app version, platform, and steps to reproduce.</p><h2 id="a-translation-source-suddenly-stopped-working-why" tabindex="-1">A translation source suddenly stopped working. Why? <a class="header-anchor" href="#a-translation-source-suddenly-stopped-working-why" aria-label="Permalink to &quot;A translation source suddenly stopped working. Why?&quot;">​</a></h2><p>The free translation sources use public web endpoints rather than official APIs, so a provider can change or block an endpoint at any time. Disable that source in the translation settings and use the others, or switch to an official API source. See <a href="./translation.html">Translation</a> for details.</p>`,27)]))}const g=a(s,[["render",r]]);export{p as __pageData,g as default};
